def transform(grid):
    h, w = len(grid), len(grid[0])

    horizon_crosses = []
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            horizon_crosses.append(r)

    vert_cross = None
    for c in range(w):
        if len(set(grid[r][c] for r in range(h))) == 1 and grid[0][c] != 0:
            vert_cross = c
            break

    if vert_cross is not None and len(horizon_crosses) >= 2:
        source_rows = [i for i in range(horizon_crosses[-1] + 1, h)]
    else:
        source_rows = [i for i in range(h)]

    if vert_cross is not None and len(horizon_crosses) >= 2:
        period = horizon_crosses[-1] - horizon_crosses[0]
    else:
        period = h

    # Find input row for each output row
    out_to_in = {}
    for r in range(h):
        src_idx = r % period
        if src_idx < len(source_rows):
            out_to_in[r] = source_rows[src_idx]
        else:
            # Cross row - use the corresponding cross row from input
            out_to_in[r] = horizon_crosses[src_idx % len(horizon_crosses)]

    # Build output grid
    output = []
    for r in range(h):
        in_r = out_to_in[r]
        src_row = grid[in_r].copy()

        result = src_row[:]

        if vert_cross is not None:
            for i, val in enumerate(src_row[:vert_cross]):
                result[vert_cross + 1 + i] = val
        else:
            center = (w - 1) // 2
            for i, val in enumerate(src_row[:center]):
                result[w - 1 - i] = val

        output.append(result)

    # Draw horizontal crosses back in their original positions
    for rc in horizon_crosses:
        for c in range(w):
            output[rc][c] = grid[rc][0]

    # Draw vertical cross if present
    if vert_cross is not None:
        for r in range(h):
            output[r][vert_cross] = grid[0][vert_cross]

    return output

